'use strict';

const path = require('path');

const HKM_FAIL = 0xffffffff;
const HKM_IGNORE_VID_PID = 0x10000;
const HDT_ALL = 0;
const HDT_KM = 1;
const HDT_KEY = 2;
const HDT_MOUSE = 3;
const DPIM_PHYSICAL = 0;
const DPIM_CURRENT = 4;
const HDEMI_MOVE = 0x02;
const HDEMM_ABS = 0x02;
const STANDARD_DLL_NAME = 'wyhkm.dll';
const REDUCED_DLL_NAME = 'wyhr.dll';

let cachedBindings = null;

function getDefaultDllPath(options = {}) {
  const edition = options.edition === 'reduced' || options.edition === '精简版' ? '精简版' : '标准版';
  const archDir = process.arch === 'ia32' ? '32位模块' : '64位模块';
  const dllName = edition === '精简版' ? REDUCED_DLL_NAME : STANDARD_DLL_NAME;
  return path.join(__dirname, '..', edition, archDir, dllName);
}

function assertWindows() {
  if (process.platform !== 'win32') {
    throw new Error('Wuya HKM DLL can only be loaded on Windows');
  }
}

function loadBindings(options = {}) {
  assertWindows();

  const dllPath = options.dllPath || getDefaultDllPath(options);
  if (cachedBindings && cachedBindings.dllPath === dllPath) {
    return cachedBindings;
  }

  const koffi = require('koffi');
  const dll = koffi.load(dllPath);

  cachedBindings = {
    dllPath,
    HKMGetVersion: dll.func('uint32_t __stdcall HKMGetVersion()'),
    HKMSearchDevice: dll.func('uint32_t __stdcall HKMSearchDevice(uint32_t dwVid, uint32_t dwPid, uint32_t dwDeviceType)'),
    HKMSearchDeviceAll: dll.func('void * __stdcall HKMSearchDeviceAll(uint32_t dwVid, uint32_t dwPid, uint32_t dwDeviceType)'),
    HKMOpen: dll.func('void * __stdcall HKMOpen(uint32_t dwDeviceId, uint32_t dwDpiMode)'),
    HKMIsOpen: dll.func('int __stdcall HKMIsOpen(void *lpHKMData, uint32_t dwFlags)'),
    HKMClose: dll.func('int __stdcall HKMClose(void *lpHKMData)'),
    HKMGetError: safeFunc(dll, 'uint32_t __stdcall HKMGetError(void *lpHKMData)'),
    HKMGetMouseMode: dll.func('uint32_t __stdcall HKMGetMouseMode(void *lpHKMData)'),
    HKMGetDataCount: dll.func('uint32_t __stdcall HKMGetDataCount(void *lpData)'),
    HKMGetDataUnitInt: dll.func('uint32_t __stdcall HKMGetDataUnitInt(void *lpData, uint32_t dwIndex)'),
    HKMFreeData: dll.func('int __stdcall HKMFreeData(void *lpData)'),
    HKMSetMode: dll.func('int __stdcall HKMSetMode(void *lpHKMData, uint32_t dwIndex, uint32_t dwMode)'),
    HKMSetKeyInterval: dll.func('int __stdcall HKMSetKeyInterval(void *lpHKMData, uint32_t dwMinTime, uint32_t dwMaxTime)'),
    HKMSetAbsMouseScrnRes: dll.func('int __stdcall HKMSetAbsMouseScrnRes(void *lpHKMData, int32_t lWidth, int32_t lHeight)'),
    HKMGetCursorPos2: dll.func('uint32_t __stdcall HKMGetCursorPos2(void *lpHKMData)'),
    HKMMoveTo: dll.func('int __stdcall HKMMoveTo(void *lpHKMData, int32_t nX, int32_t nY)'),
    HKMMoveR: dll.func('int __stdcall HKMMoveR(void *lpHKMData, int32_t nX, int32_t nY)'),
    HKMMoveR2: safeFunc(dll, 'int __stdcall HKMMoveR2(void *lpHKMData, int32_t nX, int32_t nY)'),
    HKMLeftClick: dll.func('int __stdcall HKMLeftClick(void *lpHKMData)'),
    HKMRightClick: dll.func('int __stdcall HKMRightClick(void *lpHKMData)'),
    HKMMiddleClick: dll.func('int __stdcall HKMMiddleClick(void *lpHKMData)'),
    HKMLeftDown: dll.func('int __stdcall HKMLeftDown(void *lpHKMData)'),
    HKMRightDown: dll.func('int __stdcall HKMRightDown(void *lpHKMData)'),
    HKMMiddleDown: dll.func('int __stdcall HKMMiddleDown(void *lpHKMData)'),
    HKMLeftUp: dll.func('int __stdcall HKMLeftUp(void *lpHKMData)'),
    HKMRightUp: dll.func('int __stdcall HKMRightUp(void *lpHKMData)'),
    HKMMiddleUp: dll.func('int __stdcall HKMMiddleUp(void *lpHKMData)'),
    HKMMouseWheel: dll.func('int __stdcall HKMMouseWheel(void *lpHKMData, int32_t nCount)'),
    HKMKeyPress: dll.func('int __stdcall HKMKeyPress(void *lpHKMData, const wchar_t *lpKeyName)'),
    HKMKeyDown: dll.func('int __stdcall HKMKeyDown(void *lpHKMData, const wchar_t *lpKeyName)'),
    HKMKeyUp: dll.func('int __stdcall HKMKeyUp(void *lpHKMData, const wchar_t *lpKeyName)'),
    HKMOutputString: dll.func('int __stdcall HKMOutputString(void *lpHKMData, const wchar_t *lpString)')
  };

  return cachedBindings;
}

function safeFunc(dll, signature) {
  try {
    return dll.func(signature);
  } catch (_error) {
    return null;
  }
}

function isFail(value) {
  return value === HKM_FAIL || value === -1;
}

module.exports = {
  DPIM_CURRENT,
  DPIM_PHYSICAL,
  HDT_ALL,
  HDT_KM,
  HDT_KEY,
  HDT_MOUSE,
  HKM_IGNORE_VID_PID,
  HDEMI_MOVE,
  HDEMM_ABS,
  HKM_FAIL,
  getDefaultDllPath,
  isFail,
  loadBindings
};
